import {notFound} from "next/navigation";import {getPublicLearner} from "@/lib/gamification/queries";
export default async function LearnerPage({params}:{params:Promise<{publicProfileId:string}>}){const p=await getPublicLearner((await params).publicProfileId);if(!p)notFound();return <main className="min-h-screen bg-slate-50 px-4 py-12"><article className="mx-auto max-w-2xl rounded-3xl bg-white p-8 shadow-sm"><h1 className="text-3xl font-black">{p.name}</h1><div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["XP",p.xp],["Rank",p.weeklyRank?`#${p.weeklyRank}`:"—"],["Streak",p.currentStreak],["Best",p.bestStreak]].map(([k,v])=><div className="rounded-xl bg-slate-100 p-4" key={k}><p className="text-sm text-slate-500">{k}</p><strong className="text-xl">{v}</strong></div>)}</div><h2 className="mt-8 text-xl font-black">Recent Ranked Challenges</h2>{p.challenges.length?<ul className="mt-3 grid gap-2">{p.challenges.map((c,i)=><li className="rounded-lg border p-3" key={i}>{c.type.replaceAll("_"," ")} · {c.total}</li>)}</ul>:<p className="mt-2 text-slate-500">No completed challenges yet.</p>}</article></main>}
